type cell struct{ r, c int }

func main() {
	in := bufio.NewReader(os.Stdin)
	var rows, cols int
	if _, err := fmt.Fscan(in, &rows, &cols); err != nil {
		return
	}
	grid := make([]string, rows)
	for r := 0; r < rows; r++ {
		if _, err := fmt.Fscan(in, &grid[r]); err != nil {
			return
		}
	}
	if grid[0][0] == '#' || grid[rows-1][cols-1] == '#' {
		fmt.Println(-1)
		return
	}
	dist := make([][]int, rows)
	for r := range dist {
		dist[r] = make([]int, cols)
		for c := range dist[r] {
			dist[r][c] = -1
		}
	}
	dist[0][0] = 0
	queue := []cell{{0, 0}}
	steps := []cell{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	for head := 0; head < len(queue); head++ {
		at := queue[head]
		for _, s := range steps {
			nr, nc := at.r+s.r, at.c+s.c
			if nr < 0 || nc < 0 || nr >= rows || nc >= cols {
				continue
			}
			if dist[nr][nc] >= 0 || grid[nr][nc] != '.' {
				continue
			}
			dist[nr][nc] = dist[at.r][at.c] + 1
			queue = append(queue, cell{nr, nc})
		}
	}
	fmt.Println(dist[rows-1][cols-1])
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String[] head = in.readLine().trim().split("\\s+");
        int rows = Integer.parseInt(head[0]);
        int cols = Integer.parseInt(head[1]);
        String[] grid = new String[rows];
        for (int r = 0; r < rows; r++) grid[r] = in.readLine();

        if (grid[0].charAt(0) == '#' || grid[rows - 1].charAt(cols - 1) == '#') {
            System.out.println(-1);
            return;
        }
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) java.util.Arrays.fill(row, -1);
        dist[0][0] = 0;
        Deque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[] {0, 0});
        int[][] steps = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!queue.isEmpty()) {
            int[] at = queue.poll();
            for (int[] s : steps) {
                int nr = at[0] + s[0];
                int nc = at[1] + s[1];
                if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
                if (dist[nr][nc] >= 0 || grid[nr].charAt(nc) != '.') continue;
                dist[nr][nc] = dist[at[0]][at[1]] + 1;
                queue.add(new int[] {nr, nc});
            }
        }
        System.out.println(dist[rows - 1][cols - 1]);
    }
}

