package main

import (
	"bufio"
	"fmt"
	"os"
)

type point struct{ x, y int }

type heading struct {
	name   string
	dx, dy int
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var k int
	if _, err := fmt.Fscan(in, &k); err != nil {
		return
	}
	blocked := make(map[point]bool, k)
	for i := 0; i < k; i++ {
		var p point
		if _, err := fmt.Fscan(in, &p.x, &p.y); err != nil {
			return
		}
		blocked[p] = true
	}
	var commands string
	if _, err := fmt.Fscan(in, &commands); err != nil {
		return
	}

	// Headings clockwise from north, so R is one step forward in this list.
	headings := []heading{{"N", 0, 1}, {"E", 1, 0}, {"S", 0, -1}, {"W", -1, 0}}
	facing := 0
	at := point{}
	for _, c := range commands {
		switch c {
		case 'R':
			facing = (facing + 1) % 4
		case 'L':
			facing = (facing + 3) % 4
		default:
			next := point{at.x + headings[facing].dx, at.y + headings[facing].dy}
			if !blocked[next] {
				at = next
			}
		}
	}
	fmt.Println(at.x, at.y, headings[facing].name)
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int k = Integer.parseInt(in.readLine().trim());
        Set<String> blocked = new HashSet<>();
        for (int i = 0; i < k; i++) {
            String[] parts = in.readLine().trim().split("\\s+");
            blocked.add(parts[0] + ":" + parts[1]);
        }
        String commands = in.readLine().trim();

        // Headings clockwise from north, so R is one step forward in this list.
        String[] names = {"N", "E", "S", "W"};
        int[] dx = {0, 1, 0, -1};
        int[] dy = {1, 0, -1, 0};
        int facing = 0;
        int x = 0;
        int y = 0;
        for (char c : commands.toCharArray()) {
            if (c == 'R') {
                facing = (facing + 1) % 4;
            } else if (c == 'L') {
                facing = (facing + 3) % 4;
            } else {
                int nx = x + dx[facing];
                int ny = y + dy[facing];
                if (!blocked.contains(nx + ":" + ny)) {
                    x = nx;
                    y = ny;
                }
            }
        }
        System.out.println(x + " " + y + " " + names[facing]);
    }
}
